{"requirements": [
  {
    "id": 1,
    "text": "The system shall display the game's goal, which is to grow the length of the snake by making the snake eat food until it fills the entire board."
  },
  {
    "id": 2,
    "text": "The system shall detect when the snake touches food on the board and increment the snake's body length by one block."
  },
  {
    "id": 3,
    "text": "The system shall ensure that the snake's body grows by one block when it eats a piece of food, and the new block is attached to the end of the body."
  },
  {
    "id": 4,
    "text": "The system shall prevent the snake from touching any side of the board."
  },
  {
    "id": 5,
    "text": "The system shall end the game as soon as the snake's body is touched."
  },
  {
    "id": 6,
    "text": "The system shall initialize the game board with a snake and a piece of food, where the board size is given as input by the user."
  },
  {
    "id": 7,
    "text": "The system shall represent the snake as a single green block, positioned at the bottom left square of the board, and the food as a single red block at a random position on the board."
  },
  {
    "id": 8,
    "text": "The system shall allow the user to move the snake by pressing up, down, right, or left on the keyboard."
  },
  {
    "id": 9,
    "text": "The system shall display a new piece of food on the board after the snake eats a piece of food."
  },
  {
    "id": 10,
    "text": "The system shall increase the snake's speed by 10 milliseconds every time the snake eats a piece of food."
  },
  {
    "id": 11,
    "text": "The system shall set the snake's initial speed to 0.5 blocks per second when the user selects the 'easy' difficulty level."
  },
  {
    "id": 12,
    "text": "The system shall display a blue bonus piece of food on the board after the snake has eaten many pieces of food."
  },
  {
    "id": 13,
    "text": "The system shall display a golden bonus block on the board occasionally, and the snake shall eat it to decrease its speed by 5%."
  },
  {
    "id": 14,
    "text": "The system shall pause the game when the user presses 'p' on the keyboard until the user presses 'q' again."
  }
]}
